import json
import csv
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def read_csv_file(filepath):
    """Read CSV file and return list of dicts."""
    data = []
    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            data.append(row)
    return data

def excel_serial_to_date(serial):
    """Convert Excel serial number to YYYY-MM-DD string."""
    if not serial:
        return None
    try:
        # Excel's epoch is 1899-12-30
        base = datetime(1899, 12, 30)
        days = int(float(serial))
        date = base + timedelta(days=days)
        return date.strftime("%Y-%m-%d")
    except:
        return None

def process_packet(packet_dir, manifest):
    """Main processing function."""
    # Load manifest
    pairs = manifest["pairs"]
    facts = manifest["facts"]

    # Prepare result structure
    result = {}

    # Read all CSV files in packet directory
    csv_files = {}
    for file in Path(packet_dir).glob("*.csv"):
        filename = file.stem  # Without extension
        csv_files[filename] = read_csv_file(file)

    # Group pairs by rule_id and entity
    pair_map = {}
    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        if rule_id not in pair_map:
            pair_map[rule_id] = {}
        if entity not in pair_map[rule_id]:
            pair_map[rule_id][entity] = []
        pair_map[rule_id][entity].append(pair)

    # Process each rule
    for rule_id, entities in pair_map.items():
        rule_facts = facts[rule_id]

        for entity, pair_list in entities.items():
            for pair in pair_list:
                result[pair] = {}

                # Find entity in CSV files
                entity_data = []
                for filename, rows in csv_files.items():
                    for row in rows:
                        # Look for CASE_NUMBER or similar identifier
                        case_num = row.get("CASE_NUMBER", "")
                        if case_num == entity:
                            entity_data.append((filename, row))

                if not entity_data:
                    # No records found for this entity
                    for fact in rule_facts:
                        result[pair][fact] = "ABSENT"
                    continue

                # Check for conflicts across documents
                if len(entity_data) > 1:
                    # Multiple documents with same entity - check for conflicts
                    conflict_check = {}
                    for filename, row in entity_data:
                        for fact in rule_facts:
                            if fact not in conflict_check:
                                conflict_check[fact] = {}

                            value = extract_fact_value(rule_id, fact, row)
                            if value is not None:
                                key = (value, filename)
                                if key not in conflict_check[fact]:
                                    conflict_check[fact][key] = 0
                                conflict_check[fact][key] += 1

                    # Determine final value for each fact
                    for fact in rule_facts:
                        if not conflict_check[fact]:
                            result[pair][fact] = "ABSENT"
                        elif len(conflict_check[fact]) == 1:
                            # Only one unique value
                            (value, filename), _ = list(conflict_check[fact].items())[0]
                            result[pair][fact] = [value, filename]
                        else:
                            # Multiple different values
                            result[pair][fact] = "CONFLICT"
                else:
                    # Single document
                    filename, row = entity_data[0]
                    for fact in rule_facts:
                        value = extract_fact_value(rule_id, fact, row)
                        if value is None:
                            result[pair][fact] = "ABSENT"
                        else:
                            result[pair][fact] = [value, filename]

    return result

def extract_fact_value(rule_id, fact_name, row):
    """Extract fact value from a row based on rule and fact name."""
    if rule_id == "lca.wage_105":
        if fact_name == "offered wage":
            value = row.get("WAGE_RATE_OF_PAY_FROM", "").strip()
            if not value:
                return None
            # Convert to decimal string
            try:
                # Remove any commas, dollar signs, etc.
                value = value.replace(",", "").replace("$", "").strip()
                # Check if it's a range like "84000,"
                if "," in value:
                    value = value.split(",")[0]
                # Convert to float and back to string to normalize
                return str(float(value))
            except:
                return None
        elif fact_name == "prevailing wage":
            value = row.get("PREVAILING_WAGE", "").strip()
            if not value:
                return None
            try:
                value = value.replace(",", "").replace("$", "").strip()
                return str(float(value))
            except:
                return None

    elif rule_id == "lca.three_years":
        if fact_name == "begin date":
            value = row.get("BEGIN_DATE", "").strip()
            return excel_serial_to_date(value)
        elif fact_name == "end date":
            value = row.get("END_DATE", "").strip()
            return excel_serial_to_date(value)

    return None

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Read manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Process packet
    result = process_packet(packet_dir, manifest)

    # Output result as JSON
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

