import json
import csv
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path

def parse_excel_date(excel_date):
    """Convert Excel serial date to YYYY-MM-DD string."""
    if excel_date == "":
        return None
    try:
        # Excel's epoch is 1899-12-30 (with 1900 incorrectly treated as leap year)
        # We'll handle it as days since 1899-12-30
        days = int(float(excel_date))
        base = datetime(1899, 12, 30)
        date = base + timedelta(days=days)
        return date.strftime("%Y-%m-%d")
    except (ValueError, TypeError):
        return None

def load_lca_disclosure(packet_dir):
    """Load and parse lca_disclosure.csv file."""
    file_path = Path(packet_dir) / "lca_disclosure.csv"
    if not file_path.exists():
        return {}

    records = {}
    with open(file_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            case_number = row['CASE_NUMBER']
            records[case_number] = {
                'offered_wage': row.get('WAGE_RATE_OF_PAY_FROM', '').strip(),
                'prevailing_wage': row.get('PREVAILING_WAGE', '').strip(),
                'begin_date': row.get('BEGIN_DATE', '').strip(),
                'end_date': row.get('END_DATE', '').strip()
            }
    return records

def process_wage_value(wage_str):
    """Process wage string to decimal string."""
    if not wage_str:
        return None
    try:
        # Remove commas and convert to float, then format as decimal string
        cleaned = wage_str.replace(',', '')
        value = float(cleaned)
        # Format without scientific notation
        if value.is_integer():
            return str(int(value))
        return str(value)
    except (ValueError, AttributeError):
        return None

def main():
    if len(sys.argv) != 3:
        print("Usage: python3 program.py <packet_directory> <manifest.json>")
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    # Load manifest
    with open(manifest_path, 'r') as f:
        manifest = json.load(f)

    # Load data from files
    lca_data = load_lca_disclosure(packet_dir)

    # Prepare result structure
    result = {}

    # Process each pair
    for pair in manifest['pairs']:
        rule_id, entity = pair.split('::', 1)

        if rule_id not in result:
            result[rule_id] = {}

        if entity not in result[rule_id]:
            result[rule_id][entity] = {}

        # Get facts for this rule
        fact_names = manifest['facts'][rule_id]

        # Get entity data
        entity_data = lca_data.get(entity, {})

        # Process each fact based on rule
        for fact_name in fact_names:
            if rule_id == 'lca.wage_105':
                if fact_name == 'offered wage':
                    wage_val = process_wage_value(entity_data.get('offered_wage'))
                    if wage_val:
                        result[rule_id][entity][fact_name] = [wage_val, "lca_disclosure"]
                    else:
                        result[rule_id][entity][fact_name] = "ABSENT"
                elif fact_name == 'prevailing wage':
                    wage_val = process_wage_value(entity_data.get('prevailing_wage'))
                    if wage_val:
                        result[rule_id][entity][fact_name] = [wage_val, "lca_disclosure"]
                    else:
                        result[rule_id][entity][fact_name] = "ABSENT"

            elif rule_id == 'lca.three_years':
                if fact_name == 'begin date':
                    date_val = parse_excel_date(entity_data.get('begin_date'))
                    if date_val:
                        result[rule_id][entity][fact_name] = [date_val, "lca_disclosure"]
                    else:
                        result[rule_id][entity][fact_name] = "ABSENT"
                elif fact_name == 'end date':
                    date_val = parse_excel_date(entity_data.get('end_date'))
                    if date_val:
                        result[rule_id][entity][fact_name] = [date_val, "lca_disclosure"]
                    else:
                        result[rule_id][entity][fact_name] = "ABSENT"

    # Convert to required output format
    output = {}
    for rule_id, entities in result.items():
        for entity, facts in entities.items():
            pair_key = f"{rule_id}::{entity}"
            output[pair_key] = facts

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

